import { MemoryRouter, Route, Routes } from "react-router-dom";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
 
import report from "./fixtures/report.json";
import runCompleted from "./fixtures/run_completed.json";
import runFailed from "./fixtures/run_failed.json";
import runRunning from "./fixtures/run_running.json";
import authResponse from "./fixtures/auth_response.json";
 
vi.mock("../services/api", () => ({
  API_BASE: "http://test",
  getRun: vi.fn(),
  getReport: vi.fn(),
  login: vi.fn(),
  register: vi.fn(),
  startRun: vi.fn(),
  listReports: vi.fn(),
}));
 
import AgentLogsPanel from "../components/AgentLogsPanel";
import AppShell from "../components/AppShell";
import { GuestRoute, ProtectedRoute } from "../components/ProtectedRoute";
import { useRunPolling } from "../hooks/useRunPolling";
import LiveProgress from "../pages/LiveProgress";
import Login from "../pages/Login";
import ReportView from "../pages/ReportView";
import * as api from "../services/api";
import { AGENT_LABELS, money } from "../services/format";
import { useAuthStore } from "../store/authStore";
 
beforeEach(() => {
  useAuthStore.setState({ token: null, user: null });
  Object.values(api).forEach((fn) => typeof fn?.mockReset === "function" && fn.mockReset());
});
 
// --------------------------------------------------------------- Agent Logs Panel
describe("AgentLogsPanel", () => {
  it("shows all five agents in pipeline order, each with its own status", () => {
    render(<AgentLogsPanel agents={runRunning.agents} />);
    const L = AGENT_LABELS;
    expect(screen.getByLabelText(`${L.preprocessor}: done`)).toBeInTheDocument();
    expect(screen.getByLabelText(`${L.technical_analyst}: done`)).toBeInTheDocument();
    expect(screen.getByLabelText(`${L.sentiment}: running`)).toBeInTheDocument();
    expect(screen.getByLabelText(`${L.forecasting}: queued`)).toBeInTheDocument();
    expect(screen.getByLabelText(`${L.risk}: queued`)).toBeInTheDocument();
    expect(screen.getAllByRole("listitem", { name: /: (done|running|queued)$/ })).toHaveLength(5);
  });
 
  it("narrates only the agent that is working, and shows finished agents' log lines", () => {
    render(<AgentLogsPanel agents={runRunning.agents} />);
    expect(screen.getByText(/Reading recent headlines/)).toBeInTheDocument();
    expect(screen.queryByText(/Fetching and cleaning/)).not.toBeInTheDocument();
    expect(screen.getByText("Preprocessor → Done (251 rows cleaned)")).toBeInTheDocument();
  });
 
  it("explains failed and skipped agents instead of leaving them blank", () => {
    render(<AgentLogsPanel agents={runFailed.agents} />);
    expect(screen.getByLabelText(`${AGENT_LABELS.preprocessor}: failed`)).toBeInTheDocument();
    expect(screen.getByLabelText(`${AGENT_LABELS.technical_analyst}: skipped`)).toBeInTheDocument();
    expect(screen.getByText("Skipped: preprocessing failed, no data to analyze")).toBeInTheDocument();
    expect(screen.getAllByText(/No data returned for 'ZZZZ'/).length).toBeGreaterThan(0);
  });

  it("shows a failure's reason once, not again under its own log line", () => {
    const agents = [{ name: "preprocessor", status: "failed", message: "No data returned for 'ZZZZ'.",
                      log: ["Preprocessor → Failed (No data returned for 'ZZZZ'.)"] }];
    render(<AgentLogsPanel agents={agents} />);
    expect(screen.getAllByText(/No data returned for 'ZZZZ'/)).toHaveLength(1);
  });
});
 
// ---------------------------------------------------------------- polling hook
describe("useRunPolling", () => {
  beforeEach(() => vi.useFakeTimers());
  afterEach(() => vi.useRealTimers());
  const advance = (ms) => act(async () => { await vi.advanceTimersByTimeAsync(ms); });
 
  it("keeps polling while the run is active, then stops once it finishes", async () => {
    api.getRun
      .mockResolvedValueOnce(runRunning)
      .mockResolvedValueOnce(runRunning)
      .mockResolvedValue(runCompleted);
    const { result } = renderHook(() => useRunPolling("abc", 2000));
 
    await advance(0);
    expect(result.current.run.status).toBe("running");
    await advance(2000);
    await advance(2000);
    expect(result.current.run.status).toBe("completed");
 
    const callsWhenDone = api.getRun.mock.calls.length;
    await advance(20000);
    expect(api.getRun.mock.calls.length).toBe(callsWhenDone); // no more requests
  });
 
  it("stops at once, with a clear message, when the run doesn't exist", async () => {
    api.getRun.mockRejectedValue({ response: { status: 404 } });
    const { result } = renderHook(() => useRunPolling("nope", 2000));
    await advance(0);
    expect(result.current.error).toBe("This analysis could not be found.");
    await advance(30000);
    expect(api.getRun).toHaveBeenCalledTimes(1);
  });
 
  it("survives one failed request, but gives up after five in a row", async () => {
    api.getRun.mockRejectedValueOnce({ request: {} }).mockResolvedValue(runRunning);
    const ok = renderHook(() => useRunPolling("abc", 1000));
    await advance(0);
    expect(ok.result.current.error).toBeNull();
    await advance(2000);
    expect(ok.result.current.run.status).toBe("running");
    ok.unmount();
 
    api.getRun.mockReset();
    api.getRun.mockRejectedValue({ request: {} });
    const bad = renderHook(() => useRunPolling("abc", 1000));
    await advance(60000);
    expect(api.getRun).toHaveBeenCalledTimes(5);
    expect(bad.result.current.error).toMatch(/Can't reach the server/);
  });
 
  it("stops polling when the page is left", async () => {
    api.getRun.mockResolvedValue(runRunning);
    const { unmount } = renderHook(() => useRunPolling("abc", 1000));
    await advance(0);
    unmount();
    const calls = api.getRun.mock.calls.length;
    await advance(10000);
    expect(api.getRun.mock.calls.length).toBe(calls);
  });
});
 
// ------------------------------------------------------------------ live progress
describe("LiveProgress page", () => {
  const renderPage = () =>
    render(
      <MemoryRouter initialEntries={["/analysis/abc"]}>
        <Routes><Route path="/analysis/:runId" element={<LiveProgress />} /></Routes>
      </MemoryRouter>
    );
 
  it("while running: shows progress and no report link yet", async () => {
    api.getRun.mockResolvedValue(runRunning);
    renderPage();
    expect(await screen.findByRole("heading", { name: runRunning.ticker })).toBeInTheDocument();
    expect(screen.getByRole("status")).toHaveTextContent(/1–2 minutes/);
    expect(screen.queryByRole("link", { name: /View report/ })).not.toBeInTheDocument();
  });
 
  it("when completed: offers the report", async () => {
    api.getRun.mockResolvedValue(runCompleted);
    renderPage();
    const link = await screen.findByRole("link", { name: /View report/ });
    expect(link).toHaveAttribute("href", `/reports/${runCompleted.report_id}`);
  });
 
  it("when failed: shows the reason and a way to try again", async () => {
    api.getRun.mockResolvedValue(runFailed);
    renderPage();
    expect((await screen.findAllByText(runFailed.error)).length).toBeGreaterThan(0);
    expect(screen.getByRole("link", { name: /Try another ticker/ })).toBeInTheDocument();
  });
});
 
// -------------------------------------------------------------------- report view
describe("ReportView", () => {
  const renderReport = (path = "/reports/r1") =>
    render(
      <MemoryRouter initialEntries={[path]}>
        <Routes><Route path="/reports/:reportId" element={<ReportView />} /></Routes>
      </MemoryRouter>
    );
 
  it("opens on the overview: ledger rows, analyst note, disclaimer", async () => {
    api.getReport.mockResolvedValue(report);
    renderReport();
    expect(await screen.findByRole("heading", { name: report.ticker })).toBeInTheDocument();
    expect(screen.getByText(report.summary)).toBeInTheDocument();
    expect(screen.getByText(/30-day outlook · ARIMA/)).toBeInTheDocument();
    expect(screen.getByText(report.overview.forecast_models_agree ? "models agree" : "models disagree")).toBeInTheDocument();
    expect(screen.getByText(report.disclaimer)).toBeInTheDocument();
    expect(screen.getByRole("tab", { name: "Overview" })).toHaveAttribute("aria-selected", "true");
  });
 
  it("an Indian stock reads in rupees everywhere, a US stock in dollars", async () => {
    // (the fixture's written summary is in dollars, so swap it: the backend writes it in the report's currency)
    const inr = { ...report, ticker: "RELIANCE.NS", summary: "Analyst note.",
                  overview: { ...report.overview, ticker: "RELIANCE.NS", currency: "INR" } };
    api.getReport.mockResolvedValue(inr);
    renderReport();
    expect(await screen.findByText(money(report.overview.latest_close, "INR"))).toBeInTheDocument();
    expect(screen.queryByText(/\$/)).not.toBeInTheDocument();
    await userEvent.click(screen.getByRole("tab", { name: "Prediction" }));
    expect(await screen.findByText(money(report.forecast.forecast_final_price, "INR"))).toBeInTheDocument();
    await userEvent.click(screen.getByRole("tab", { name: "Risk" }));
    expect(await screen.findByText(money(report.risk.monte_carlo.median_final_price, "INR"))).toBeInTheDocument();
  });

  it("a flat ARIMA forecast is not called a disagreement with LSTM", async () => {
    api.getReport.mockResolvedValue({ ...report, overview: { ...report.overview, forecast_models_agree: null } });
    renderReport();
    expect(await screen.findByText("one model sees no move")).toBeInTheDocument();
    expect(screen.queryByText("models disagree")).not.toBeInTheDocument();
  });

  it("a report from before currencies were recorded still shows dollars", async () => {
    const { currency: _drop, ...overview } = report.overview;
    api.getReport.mockResolvedValue({ ...report, overview });
    renderReport();
    expect(await screen.findByText(money(report.overview.latest_close, "USD"))).toBeInTheDocument();
  });

  it("Technical tab draws close, SMA and EMA lines", async () => {
    api.getReport.mockResolvedValue(report);
    const { container } = renderReport();
    await userEvent.click(await screen.findByRole("tab", { name: "Technical" }));
    expect(screen.getByRole("tab", { name: "Technical" })).toHaveAttribute("aria-selected", "true");
    await waitFor(() => expect(container.querySelectorAll(".recharts-line")).toHaveLength(3));
  });
 
  it("Prediction tab draws the price, both model forecasts and the ARIMA band", async () => {
    api.getReport.mockResolvedValue(report);
    const { container } = renderReport();
    await userEvent.click(await screen.findByRole("tab", { name: "Prediction" }));
    await waitFor(() => expect(container.querySelectorAll(".recharts-line")).toHaveLength(3)); // close, arima, lstm
    expect(container.querySelectorAll(".recharts-area").length).toBeGreaterThan(0);
    expect(screen.getByText(/The two models/)).toBeInTheDocument();
  });
 
  it("Risk tab shows the metrics and the Monte Carlo fan", async () => {
    api.getReport.mockResolvedValue(report);
    const { container } = renderReport();
    await userEvent.click(await screen.findByRole("tab", { name: "Risk" }));
    expect(screen.getByText("Sharpe ratio")).toBeInTheDocument();
    expect(screen.getByText("Chance of a lower price")).toBeInTheDocument();
    await waitFor(() => expect(container.querySelectorAll(".recharts-area").length).toBeGreaterThan(0));
  });
 
  it("Sentiment tab lists the headlines that were scored", async () => {
    api.getReport.mockResolvedValue(report);
    renderReport();
    await userEvent.click(await screen.findByRole("tab", { name: "Sentiment" }));
    const firstTitle = report.sentiment.headlines[0].split(" - ")[0];
    expect(await screen.findByText(firstTitle)).toBeInTheDocument();
  });
 
  it("the active tab lives in the URL, so a refresh or shared link lands on it", async () => {
    api.getReport.mockResolvedValue(report);
    renderReport("/reports/r1?tab=risk");
    expect(await screen.findByRole("tab", { name: "Risk" })).toHaveAttribute("aria-selected", "true");
    expect(screen.getByText("Sharpe ratio")).toBeInTheDocument();
  });
 
  it("arrow keys move between tabs", async () => {
    api.getReport.mockResolvedValue(report);
    renderReport();
    const overview = await screen.findByRole("tab", { name: "Overview" });
    overview.focus();
    await userEvent.keyboard("{ArrowRight}");
    expect(screen.getByRole("tab", { name: "Technical" })).toHaveAttribute("aria-selected", "true");
  });
 
  it("a missing section says why, instead of showing blanks or crashing", async () => {
    api.getReport.mockResolvedValue({
      ...report,
      forecast: null,
      errors: { forecasting: "ARIMA failed to converge" },
    });
    renderReport();
    await userEvent.click(await screen.findByRole("tab", { name: "Prediction" }));
    expect(screen.getByText(/isn't available/)).toBeInTheDocument();
    expect(screen.getByText("ARIMA failed to converge")).toBeInTheDocument();
  });
 
  it("an old report without a forecast path still renders (no chart, no crash)", async () => {
    const { path: _path, ...forecastWithoutPath } = report.forecast;
    api.getReport.mockResolvedValue({ ...report, forecast: forecastWithoutPath });
    renderReport();
    await userEvent.click(await screen.findByRole("tab", { name: "Prediction" }));
    expect(screen.getByText(/path isn't stored/)).toBeInTheDocument();
    expect(screen.getByText(/The two models/)).toBeInTheDocument();
  });
 
  it("a report that doesn't exist gets a friendly message", async () => {
    api.getReport.mockRejectedValue({ response: { status: 404 } });
    renderReport();
    expect(await screen.findByRole("alert")).toHaveTextContent("This report could not be found.");
  });
});
 
// ------------------------------------------------------------------------- login
describe("Login page", () => {
  const renderLogin = () =>
    render(
      <MemoryRouter initialEntries={["/login"]}>
        <Routes>
          <Route path="/login" element={<GuestRoute><Login /></GuestRoute>} />
          <Route path="/" element={<p>HOME PAGE</p>} />
        </Routes>
      </MemoryRouter>
    );
 
  it("keeps the button disabled until both fields are filled", async () => {
    renderLogin();
    const button = screen.getByRole("button", { name: "Log in" });
    expect(button).toBeDisabled();
    await userEvent.type(screen.getByLabelText("Email"), "a@example.com");
    expect(button).toBeDisabled();
    await userEvent.type(screen.getByLabelText("Password"), "secret-pass");
    expect(button).toBeEnabled();
  });
 
  it("logs in: saves the session and moves on", async () => {
    api.login.mockResolvedValue(authResponse);
    renderLogin();
    await userEvent.type(screen.getByLabelText("Email"), "a@example.com");
    await userEvent.type(screen.getByLabelText("Password"), "secret-pass");
    await userEvent.click(screen.getByRole("button", { name: "Log in" }));
 
    expect(await screen.findByText("HOME PAGE")).toBeInTheDocument();
    expect(api.login).toHaveBeenCalledWith({ email: "a@example.com", password: "secret-pass" });
    expect(useAuthStore.getState().token).toBe(authResponse.access_token);
  });
 
  it("wrong password: shows the server's message, stays logged out, can retry", async () => {
    api.login.mockRejectedValue({ response: { status: 401, data: { detail: "Invalid email or password" } } });
    renderLogin();
    await userEvent.type(screen.getByLabelText("Email"), "a@example.com");
    await userEvent.type(screen.getByLabelText("Password"), "wrong-pass");
    await userEvent.click(screen.getByRole("button", { name: "Log in" }));
 
    expect(await screen.findByRole("alert")).toHaveTextContent("Invalid email or password");
    expect(useAuthStore.getState().token).toBeNull();
    expect(screen.getByRole("button", { name: "Log in" })).toBeEnabled();
  });
 
  it("tells you when the backend isn't running", async () => {
    api.login.mockRejectedValue({ request: {} });
    renderLogin();
    await userEvent.type(screen.getByLabelText("Email"), "a@example.com");
    await userEvent.type(screen.getByLabelText("Password"), "secret-pass");
    await userEvent.click(screen.getByRole("button", { name: "Log in" }));
    expect(await screen.findByRole("alert")).toHaveTextContent("Can't reach the server at http://test");
  });
});
 
// ------------------------------------------------------------------ route guards
describe("route guards", () => {
  it("send visitors without a login to /login", () => {
    render(
      <MemoryRouter initialEntries={["/secret"]}>
        <Routes>
          <Route path="/login" element={<p>LOGIN PAGE</p>} />
          <Route path="/secret" element={<ProtectedRoute><p>SECRET</p></ProtectedRoute>} />
        </Routes>
      </MemoryRouter>
    );
    expect(screen.getByText("LOGIN PAGE")).toBeInTheDocument();
    expect(screen.queryByText("SECRET")).not.toBeInTheDocument();
  });
 
  it("let logged-in users through", () => {
    useAuthStore.setState({ token: "tok", user: { name: "A" } });
    render(
      <MemoryRouter initialEntries={["/secret"]}>
        <Routes><Route path="/secret" element={<ProtectedRoute><p>SECRET</p></ProtectedRoute>} /></Routes>
      </MemoryRouter>
    );
    expect(screen.getByText("SECRET")).toBeInTheDocument();
  });
 
  it("after logging in, return you to the page you were trying to reach", () => {
    useAuthStore.setState({ token: "tok", user: { name: "A" } });
    render(
      <MemoryRouter initialEntries={[{ pathname: "/login", state: { from: { pathname: "/history" } } }]}>
        <Routes>
          <Route path="/login" element={<GuestRoute><p>LOGIN FORM</p></GuestRoute>} />
          <Route path="/history" element={<p>HISTORY PAGE</p>} />
        </Routes>
      </MemoryRouter>
    );
    expect(screen.getByText("HISTORY PAGE")).toBeInTheDocument();
  });
});
 

describe("AppShell footer", () => {
  const renderAt = (path) =>
    render(
      <MemoryRouter initialEntries={[path]}>
        <Routes>
          <Route element={<AppShell />}>
            <Route path="*" element={<p>page body</p>} />
          </Route>
        </Routes>
      </MemoryRouter>,
    );

  it("shows the short disclaimer on ordinary pages", () => {
    renderAt("/history");
    expect(screen.getByText(/not investment advice/)).toBeInTheDocument();
  });

  it("leaves it off a report page, which carries its own fuller disclaimer", () => {
    renderAt("/reports/abc123");
    expect(screen.queryByText(/not investment advice/)).not.toBeInTheDocument();
  });
});
